    print(sol.sortMatrix([[1,7,3],[9,8,2],[4,5,6]]))  # Expected [[8,2,3],[9,6,7],[4,5,1]]
    print(sol.sortMatrix([[0,1],[1,2]]))              # Expected [[2,1],[1,0]]
    print(sol.sortMatrix([[1]]))                     # Expected [[1]]

run_tests()

