class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)

        # Helper function to sort a diagonal in non-increasing order
        def sort_bottom_left(diagonal):
            diagonal.sort(reverse=True)

        # Helper function to sort a diagonal in non-decreasing order
        def sort_top_right(diagonal):
            diagonal.sort()

        # Function to get all elements of a diagonal (bottom-left)
        def get_bottom_left_diagonal(i, j):
            diagonal = []
            while i >= 0 and j < n:
                diagonal.append(grid[i][j])
                i -= 1
                j += 1
            return diagonal

        # Function to get all elements of a diagonal (top-right)
        def get_top_right_diagonal(i, j):
            diagonal = []
            while i < n and j >= 0:
                diagonal.append(grid[i][j])
                i += 1
                j -= 1
            return diagonal

        # Process bottom-left diagonals
        for i in range(n):
            for j in range(n - i):
                diagonal = get_bottom_left_diagonal(i, j)
                sort_bottom_left(diagonal)
                # Update the grid
                idx = 0
                for x in range(i, n):
                    for y in range(j, n):
                        if x - i == idx and y - j == idx:
                            grid[x][y] = diagonal[idx]
                            idx += 1
                            break

        # Process top-right diagonals
        for i in range(n):
            for j in range(i, n):
