class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)
        # Create a dictionary to hold elements by their diagonal (sum of i + j)
        diagonal_dict = {}

        # Fill the dictionary with elements grouped by their diagonal
        for i in range(n):
            for j in range(n):
                diagonal = i + j
                if diagonal not in diagonal_dict:
                    diagonal_dict[diagonal] = []
                diagonal_dict[diagonal].append(grid[i][j])

        # Sort the bottom-left triangle diagonals (i + j <= n - 1) in non-increasing order
        for diagonal in diagonal_dict:
            if diagonal <= n - 1:
                diagonal_dict[diagonal].sort(reverse=True)
            else:
                diagonal_dict[diagonal].sort()

        # Reconstruct the matrix from the sorted diagonals
        result = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                diagonal = i + j
                result[i][j] = diagonal_dict[diagonal].pop(0)

        return result

