from typing import List

class Solution:
    def minTime(self, skill: List[int], mana: List[int]) -> int:
        n = len(skill)
        m = len(mana)

        # Initialize the time array to store the finish time for each potion
        finish_time = [0] * m

        # For each potion, compute the finish time for each wizard
        for i in range(n):
            for j in range(m):
                time_ij = skill[i] * mana[j]
                if i == 0:
                    finish_time[j] = time_ij
                else:
                    finish_time[j] = max(finish_time[j], finish_time[j] + time_ij)

        return max(finish_time)

