from typing import List
import heapq

class Solution:
    def shortestDistanceAfterQueries(self, n: int, queries: List[List[int]]) -> List[int]:
        # Initial graph: directed edges from i to i+1
        graph = [[] for _ in range(n)]
        for i in range(n - 1):
            graph[i].append(i + 1)

        def dijkstra():
            dist = [float('inf')] * n
            dist[0] = 0
            heap = [(0, 0)]
            while heap:
                d, u = heapq.heappop(heap)
                if d > dist[u]:
                    continue
                for v in graph[u]:
                    if dist[v] > dist[u] + 1:
                        dist[v] = dist[u] + 1
                        heapq.heappush(heap, (dist[v], v))
            return dist[n - 1]

        result = []
        for query in queries:
            u, v = query
            graph[u].append(v)
            result.append(dijkstra())

        return result

