    def maxFrequency(self, nums: List[int], k: int, numOperations: int) -> int:
        # Sort the array to use sliding window approach
        nums.sort()

        # Binary search for the maximum possible frequency
        left = 1
        right = len(nums)
        answer = 1

        def is_possible(freq: int) -> bool:
            # We need to make at least 'freq' elements equal to the same value
            # Use sliding window to check if it's possible
            n = len(nums)
            window = 0
            total = 0

            for i in range(n):
                if i >= freq:
                    window -= nums[i - freq]
                total += nums[i]

                if i >= freq - 1:
                    if (total - window) <= k * numOperations:
                        return True
            return False

        while left <= right:
            mid = (left + right) // 2
            if is_possible(mid):
                answer = mid
                left = mid + 1
            else:
                right = mid - 1

        return answer

