from typing import List

class Solution:
    def longestSubsequence(self, nums: List[int]) -> int:
        if not nums:
            return 0

        # We use a dictionary to store the max length of subsequences ending with a certain difference.
        # dp[d] = max length of subsequence ending with difference d
        dp = {}

        max_len = 1  # At least one element is a subsequence of length 1

        for i in range(len(nums)):
            current = nums[i]
            # For each previous number, compute the difference and update dp
            for j in range(i):
                prev = nums[j]
                diff = abs(current - prev)
                # If this diff is not in dp, or if we can get a longer subsequence
                if diff not in dp or dp[diff] < dp.get(abs(prev - current), 1) + 1:
                    dp[diff] = dp.get(abs(prev - current), 1) + 1
                max_len = max(max_len, dp[diff])

        return max_len

