                return
            if not current:
                # Start with 1 or 2 (odd or even)
                for num in [1, 2]:
                    if not used[num - 1]:
                        current.append(num)
                        used[num - 1] = True
                        generate_permutations(n, current, used, result)
                        current.pop()
                        used[num - 1] = False
                return
            else:
