    def resultsArray(self, nums: List[int], k: int) -> List[int]:
        n = len(nums)
        if k > n:
            return []
        result = []
        for i in range(n - k + 1):
            subarray = nums[i:i + k]
            # Check if the subarray is sorted in ascending order and consecutive
            is_sorted = True
            for j in range(k - 1):
                if subarray[j] >= subarray[j + 1]:
                    is_sorted = False
                    break
            if not is_sorted:
                result.append(-1)
                continue
            # Check if elements are consecutive
            if max(subarray) - min(subarray) + 1 != k:
                result.append(-1)
            else:
                result.append(max(subarray))
        return result

def run_tests():
    sol = Solution()
    print(sol.resultsArray([1,2,3,4,3,2,5], 3))  # Expected: [3,4,-1,-1,-1]
    print(sol.resultsArray([2,2,2,2,2], 4))     # Expected: [-1,-1]
    print(sol.resultsArray([3,2,3,2,3,2], 2))   # Expected: [-1,3,-1,3,-1]

run_tests()

