        # 'diff' is the current score difference (Bob - Alice)

        # Since we need to track only the previous move and the difference, we'll use a DP table with these two states

        # Initialize the DP table
        from collections import defaultdict

        # For each position, we track for each possible previous move and score difference
        # dp[i][prev][diff] = count
        dp = [defaultdict(lambda: defaultdict(int)) for _ in range(n + 1)]

        # Initial state at round 0 (before any moves)
        # We can choose any move as the first one, and the score difference is 0
        for move in ['F', 'W', 'E']:
            dp[0][move][0] = 1

        # Iterate through each round
        for i in range(n):
            current_move = s[i]
            for prev_move in ['F', 'W', 'E']:
                for diff in dp[i][prev_move]:
                    count = dp[i][prev_move][diff]
                    # Now, consider all possible next moves (not equal to prev_move)
                    for next_move in ['F', 'W', 'E']:
                        if next_move == prev_move:
                            continue
                        # Compute the score difference based on the move
                        if (current_move, next_move) in [('F', 'E'), ('W', 'F'), ('E', 'W')]:
                            # Bob gets a point
                            new_diff = diff + 1
                        elif (current_move, next_move) in [('E', 'F'), ('F', 'W'), ('W', 'E')]:
                            # Alice gets a point
                            new_diff = diff - 1
                        else:
