from typing import List
import heapq

class Solution:
    def minTimeToReach(self, moveTime: List[List[int]]) -> int:
        n, m = len(moveTime), len(moveTime[0])

        # Dijkstra's algorithm using a priority queue
        # Each element is (time, row, col)
        pq = [(moveTime[0][0], 0, 0)]
        # Keep track of visited cells and the earliest time we can reach them
        visited = [[float('inf')] * m for _ in range(n)]
        visited[0][0] = moveTime[0][0]

        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right

        while pq:
            time, row, col = heapq.heappop(pq)

            if row == n - 1 and col == m - 1:
                return time

            if time > visited[row][col]:
                continue

            for dr, dc in directions:
                nr, nc = row + dr, col + dc
                if 0 <= nr < n and 0 <= nc < m:
                    # The time to move to (nr, nc) is the current time + 1
                    new_time = time + 1
                    if new_time < visited[nr][nc]:
                        visited[nr][nc] = new_time
                        heapq.heappush(pq, (new_time, nr, nc))

        return -1  # In case no path is found (though problem states it's always reachable)

