from typing import List

class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)

        # Helper function to find the number of common elements between two property lists
        def intersect(a, b):
            return len(set(a) & set(b))

        # Build adjacency list
        graph = [[] for _ in range(n)]

        for i in range(n):
            for j in range(i + 1, n):
                if intersect(properties[i], properties[j]) >= k:
                    graph[i].append(j)
                    graph[j].append(i)

        # DFS to count connected components
        visited = [False] * n

        def dfs(node):
            if visited[node]:
                return
            visited[node] = True
            for neighbor in graph[node]:
                dfs(neighbor)

        components = 0
        for i in range(n):
            if not visited[i]:
                dfs(i)
                components += 1

        return components

