    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        # Precompute the cost to transform one character to another
        def cost(a, b):
            if a == b:
                return 0
            diff = abs(ord(a) - ord(b))
            return min(diff, 26 - diff)

        # DP[i][j][k] represents the maximum length of a palindrome in s[i..j] with k operations
        n = len(s)
        dp = [[[ -1 for _ in range(k+1)] for _ in range(n)] for _ in range(n)]

        def solve(i, j, op):
            if i > j:
                return 0
            if op == 0:
                return 0
            if dp[i][j][op] != -1:
                return dp[i][j][op]
            # Base case: single character
            if i == j:
                dp[i][j][op] = 1
                return 1
            # Try to match the first and last character
            max_len = 0
            for c in range(ord('a'), ord('z') + 1):
                if op >= cost(s[i], chr(c)) + cost(s[j], chr(c)):
                    current_len = solve(i + 1, j - 1, op - cost(s[i], chr(c)) - cost(s[j], chr(c))) + 2
                    if current_len > max_len:
                        max_len = current_len
            dp[i][j][op] = max_len
            return max_len

        return solve(0, n - 1, k)

