        m = len(word2)
        n = len(word1)

        # If word2 is longer than word1, return 0
        if m > n:
            return 0

        # Initialize frequency map for window
        window_freq = {}

        # Initialize count of valid substrings
        result = 0

        # Sliding window approach
        left = 0
        for right in range(n):
            c = word1[right]
            window_freq[c] = window_freq.get(c, 0) + 1

            # Try to move left pointer as long as the window is valid
            while left <= right:
                # Check if current window meets the frequency condition
                valid = True
                for char, count in word2_freq.items():
                    if window_freq.get(char, 0) < count:
                        valid = False
                        break
                if valid:
                    result += 1
                else:
