        # dp_incr[i]: length of the longest increasing consecutive subarray ending at i
        # dp_decr[i]: length of the longest decreasing consecutive subarray ending at i
        dp_incr = [1] * n
        dp_decr = [1] * n

        for i in range(1, n):
            if nums[i] == nums[i - 1] + 1:
                dp_incr[i] = dp_incr[i - 1] + 1
            elif nums[i] == nums[i - 1] - 1:
                dp_decr[i] = dp_decr[i - 1] + 1

        # Now, we need to sum all the valid subarrays
        total = 0
        for i in range(n):
