from typing import List

class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        # Convert list of points to a set for quick lookup
        point_set = set((x, y) for x, y in points)

        max_area = -1

        # Iterate through all combinations of 4 points to form a rectangle
        from itertools import combinations

        for p1, p2, p3, p4 in combinations(points, 4):
            # Check if these four points form a rectangle with sides parallel to axes
            x1, y1 = p1
            x2, y2 = p2
            x3, y3 = p3
            x4, y4 = p4

            # Check if all four corners are correct
            if (x1 == x3 and y1 == y3) or (x1 == x4 and y1 == y4) or (x2 == x3 and y2 == y3) or (x2 == x4 and y2 == y4):
                continue

            # Check if all x's are two unique values and y's are two unique values
            xs = {x1, x2, x3, x4}
            ys = {y1, y2, y3, y4}
            if len(xs) != 2 or len(ys) != 2:
                continue

            x_min, x_max = sorted(xs)
            y_min, y_max = sorted(ys)

            # Check if any other point is inside or on the rectangle
            valid = True
            for (x, y) in point_set:
                if x_min <= x <= x_max and y_min <= y <= y_max:
                    if (x, y) in {(x_min, y_min), (x_min, y_max), (x_max, y_min), (x_max, y_max)}:
                        continue
                    else:
                        valid = False
                        break

            if valid:
                area = (x_max - x_min) * (y_max - y_min)
                if area > max_area:
                    max_area = area

        return max_area if max_area != -1 else -1

