    def separateSquares(self, squares: List[List[int]]) -> float:
        # Extract all unique y-coordinates and sort them
        y_coords = sorted({y for x, y, l in squares})
        # Add y=0 and y=max_y for boundary checks
        y_coords = [0] + y_coords + [max(y for x, y, l in squares) + 1]

        # Binary search over y-coordinates
        left = 0
        right = len(y_coords) - 1
        while left < right:
            mid = (left + right) // 2
            y = y_coords[mid]
            # Calculate area below and above y
            area_below, area_above = 0, 0
            for x, y_i, l in squares:
                if y_i + l <= y:
                    area_below += l * l
                elif y_i <= y < y_i + l:
                    area_below += (y - y_i) * l
                else:
                    area_above += l * l
            if area_below < area_above:
                left = mid + 1
            else:
                right = mid
        return y_coords[left]

