    def lengthAfterTransformations(self, s: str, t: int) -> int:
        MOD = 10**9 + 7

        # For each character, compute its contribution after t transformations
        # Each character c (not 'z') contributes (t + 1) characters
        # 'z' contributes 2^t characters
        # But we have to check which character it is

        total = 0
        for c in s:
