class Solution:
    def minimumCost(self, target: str, words: List[str], costs: List[int]) -> int:
        # Initialize a dp array where dp[i] represents the minimum cost to form the first i characters of the target
        n = len(target)
        dp = [float('inf')] * (n + 1)
        dp[0] = 0  # Base case: cost to form empty string is 0

        for i in range(1, n + 1):
            for word_idx, word in enumerate(words):
                if len(word) > i:
                    continue
                if target[:i] == word:
                    dp[i] = min(dp[i], dp[i - len(word)] + costs[word_idx])
                # Also check all prefixes of the word
                for j in range(1, len(word)):
                    if target[:i - j] == word[:j]:
                        dp[i] = min(dp[i], dp[i - j] + costs[word_idx])

        return dp[n] if dp[n] != float('inf') else -1

