        # For each index i in nums2, find k such that nums1[(i + k) % n] == nums2[i]
        match_k = set()

        for i in range(n):
            for k in range(n):
                if nums1[(i + k) % n] == nums2[i]:
                    match_k.add(k)
                    break  # No need to check other k's for this i

        # Now, for each k in match_k, count how many indices i have a match
        max_matches = 0
        for k in match_k:
            count = 0
            for i in range(n):
                if nums1[(i + k) % n] == nums2[i]:
                    count += 1
            max_matches = max(max_matches, count)

        return max_matches

