from typing import List

class Solution:
    def minRunesToAdd(self, n: int, crystals: List[int], flowFrom: List[int], flowTo: List[int]) -> int:
        # Build the graph
        graph = [[] for _ in range(n)]
        for i in range(len(flowFrom)):
            graph[flowFrom[i]].append(flowTo[i])

        # Mark which nodes have crystals
        has_crystal = [False] * n
        for c in crystals:
            has_crystal[c] = True

        # We need to find nodes that are not sources and not reachable from any source
        # We'll use BFS or DFS to find reachable nodes from sources
        visited = [False] * n
        for node in range(n):
            if has_crystal[node]:
                # BFS from this node to mark reachable nodes
                queue = [node]
                visited[node] = True
                while queue:
                    u = queue.pop(0)
                    for v in graph[u]:
                        if not visited[v]:
                            visited[v] = True
                            queue.append(v)

        # Count the number of nodes that are not visited (i.e., not reachable from any crystal node)
        count = 0
        for i in range(n):
            if not visited[i]:
                count += 1

        # Each such node needs at least one incoming edge (i.e., one rune added)
        return count

