class Solution:
    def maxPossibleScore(self, start: List[int], d: int) -> int:
        # Sort the intervals based on their starting point
        intervals = sorted([(s, s + d) for s in start])

        # Binary search for the maximum possible score
        def is_possible(target: int) -> bool:
            # This function will check if it's possible to choose numbers such that the minimum difference is at least 'target'
            # We use greedy approach to pick numbers that are as far apart as possible
            prev = -float('inf')
            for s, e in intervals:
                if e - prev < target:
                    # Not enough space to place a number that is at least 'target' away from the last one
                    return False
                # Place the number at the earliest possible point that is at least 'target' away from the last one
                if prev == -float('inf'):
                    curr = s
                else:
                    curr = max(s, prev + target)
                if curr > e:
                    return False
                prev = curr
            return True

