            return 0

        # dp[i][j]: number of ways to assign values up to index i with arr1[i] = j
        dp = [[0] * (max(nums) + 1) for _ in range(n)]

        # Base case: for index 0, arr1[0] can be from 0 to nums[0], and arr2[0] = nums[0] - arr1[0]
        for val in range(0, nums[0] + 1):
