class Solution:
    def maximumAmount(self, coins: List[List[int]]) -> int:
        m, n = len(coins), len(coins[0])

        # dp[i][j][k] represents the maximum coins at cell (i,j) with k neutralizations used
        # k can be 0, 1, or 2
        dp = [[[float('-inf')] * 3 for _ in range(n)] for _ in range(m)]

        # Initialize the starting point (0,0)
        dp[0][0][0] = coins[0][0]
        dp[0][0][1] = coins[0][0]  # Neutralize here
        dp[0][0][2] = coins[0][0]  # Neutralize here again (if allowed)

        for i in range(m):
            for j in range(n):
                if i == 0 and j == 0:
                    continue
                # Check up (i-1, j)
                if i > 0:
                    for k in range(3):
                        if dp[i-1][j][k] != float('-inf'):
                            if coins[i][j] >= 0:
                                dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k] + coins[i][j])
                            else:
                                if k < 2:
                                    dp[i][j][k+1] = max(dp[i][j][k+1], dp[i-1][j][k] + coins[i][j])
                # Check left (i, j-1)
                if j > 0:
                    for k in range(3):
                        if dp[i][j-1][k] != float('-inf'):
                            if coins[i][j] >= 0:
                                dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k] + coins[i][j])
                            else:
                                if k < 2:
                                    dp[i][j][k+1] = max(dp[i][j][k+1], dp[i][j-1][k] + coins[i][j])

        # Find the maximum value from the bottom-right cell for k=0,1,2
        result = max(dp[m-1][n-1][0], dp[m-1][n-1][1], dp[m-1][n-1][2])
        return result

