from typing import List

class Solution:
    def maximumAmount(self, coins: List[List[int]]) -> int:
        m, n = len(coins), len(coins[0])
        # dp[i][j][k] = max coins at (i, j) with k neutralizations used
        dp = [[[float('-inf') for _ in range(3)] for _ in range(n)] for _ in range(m)]

        # Starting point (0, 0)
        dp[0][0][0] = coins[0][0]
        if coins[0][0] < 0:
            dp[0][0][1] = 0  # Neutralize at start
            dp[0][0][2] = 0  # Neutralize at start and another cell (but not used yet)

        # Fill dp table
        for i in range(m):
            for j in range(n):
                if i == 0 and j == 0:
                    continue
                for k in range(3):
                    # From top (i-1, j)
                    if i > 0:
                        for k1 in range(3):
                            if dp[i-1][j][k1] != float('-inf'):
                                if k1 <= k:
                                    new_k = k1
                                else:
                                    new_k = k1 + 1
                                if new_k < 3:
                                    dp[i][j][new_k] = max(dp[i][j][new_k], dp[i-1][j][k1] + coins[i][j])
                    # From left (i, j-1)
                    if j > 0:
                        for k1 in range(3):
                            if dp[i][j-1][k1] != float('-inf'):
                                if k1 <= k:
                                    new_k = k1
                                else:
                                    new_k = k1 + 1
                                if new_k < 3:
                                    dp[i][j][new_k] = max(dp[i][j][new_k], dp[i][j-1][k1] + coins[i][j])

        # Take the max value among all 3 neutralization states at bottom-right cell
        result = max(dp[m-1][n-1][k] for k in range(3))
        return result

