class Solution:
    def findMaximumScore(self, nums: List[int]) -> int:
        n = len(nums)
        # We will keep track of the maximum score we can get from each index
        # We'll use a DP array where dp[i] is the maximum score we can get up to index i
        dp = [0] * n
        dp[0] = 0  # Starting at index 0, score is 0

        for i in range(n):
            for j in range(i + 1, n):
                # The jump from i to j has score (j - i) * nums[i]
                score = (j - i) * nums[i]
                if dp[i] + score > dp[j]:
                    dp[j] = dp[i] + score

        return dp[-1]

