        m, n = len(grid), len(grid[0])
        if grid[0][0] == 1:
            return health >= 2  # Starting cell is unsafe

        # Directions: up, down, left, right
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        # BFS: queue holds (row, col, current_health)
        from collections import deque
        queue = deque()
        queue.append((0, 0, health))
        visited = set()
        visited.add((0, 0))

        while queue:
            r, c, h = queue.popleft()
            if r == m - 1 and c == n - 1:
                return h >= 1
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n and (nr, nc) not in visited:
                    if grid[nr][nc] == 1:
                        new_health = h - 1
                        if new_health > 0:
                            visited.add((nr, nc))
                            queue.append((nr, nc, new_health))
                    else:
                        new_health = h - 0
                        if new_health > 0:
                            visited.add((nr, nc))
                            queue.append((nr, nc, new_health))

        return False  # No path found or health dropped too low

