from math import gcd

class Solution:
    def gcdValues(self, nums: List[int], queries: List[int]) -> List[int]:
        # Compute all unique GCDs of pairs (i, j) for i < j
        n = len(nums)
        gcd_pairs = set()

        for i in range(n):
            for j in range(i + 1, n):
                gcd_pairs.add(gcd(nums[i], nums[j]))

        # Convert to sorted list
        sorted_gcds = sorted(gcd_pairs)

        # Prepare answer based on queries
        answer = []
        for q in queries:
            if q < len(sorted_gcds):
                answer.append(sorted_gcds[q])
            else:
                answer.append(-1)  # Invalid index if query exceeds the list length

        return answer

