from typing import List
import heapq

class Solution:
    def minTimeToReach(self, moveTime: List[List[int]]) -> int:
        n, m = len(moveTime), len(moveTime[0])
        if n == 0 or m == 0:
            return 0

        # Directions: up, down, left, right
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        # Priority queue: (time, x, y, step)
        # step is 0 for 1 second, 1 for 2 seconds
        pq = [(moveTime[0][0], 0, 0, 0)]
        visited = [[[-1 for _ in range(2)] for _ in range(m)] for _ in range(n)]
        visited[0][0][0] = 0  # step 0 (1 sec)

        while pq:
            time, x, y, step = heapq.heappop(pq)
            if x == n - 1 and y == m - 1:
                return time
            if visited[x][y][step] != -1:
                continue
            visited[x][y][step] = time

