class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        # Helper function to check if a character is a vowel
        def is_vowel(c):
            return c in {'a', 'e', 'i', 'o', 'u'}

        # Precompute list of vowels and consonants in the word
        vowels_in_word = [1 if is_vowel(c) else 0 for c in word]

        # Total number of vowels in the word
        total_vowels = sum(vowels_in_word)

        # If the total number of vowels is less than 5, return 0
        if total_vowels < 5:
            return 0

        # Use a sliding window to count substrings with all vowels and exactly k consonants
        left = 0
        consonant_count = 0
        vowel_count = 0
        result = 0

        for right in range(len(word)):
            if not is_vowel(word[right]):
                consonant_count += 1
            else:
                vowel_count += 1

            # Ensure we have all vowels (at least 5)
            if vowel_count >= 5:
                while left <= right and consonant_count > k:
                    if not is_vowel(word[left]):
                        consonant_count -= 1
                    left += 1

                if consonant_count == k:
                    result += 1

        return result

